# Now try: count consecutive horizontal bands per color
# A band is a maximal sequence of non-empty rows for that color
def find_color_bands(grid, color):
    """Find contiguous blocks of rows containing the color"""
    rows, cols = hfw(grid)
    bands = []
    current_band_start = None

    for r in range(rows):
        has_color = any(cell == color for cell in grid[r])
        if has_color:
            if current_band_start is None:
                current_band_start = r
        else:
            if current_band_start is not None:
                # End of band
                bands.append((current_band_start, r-1))
                current_band_start = None

    if current_band_start is not None:
        bands.append((current_band_start, rows-1))

    return bands

