col_counts = {}
for r, row in enumerate(grid):
    has_color = set()
    for c, val in enumerate(row):
        if val != 8:
            has_color.add(val)
    if has_color:
        for color in has_color:
            if color not in row_counts:
                row_counts[color] = []
            row_counts[color].append((r, 'has'))

# Count how many rows have each color at least once
for color in [2, 3]:
    row_count = sum(1 for r, row in enumerate(grid) if any(cell == color for cell in row))
    col_count = sum(1 for c in range(cols) if any(grid[r][c] == color for r in range(rows)))
    print(f"\n{color} appears in {row_count} rows and {col_count} columns")

# Try counting "blobs" or connected components again but report sizes
print("\n--- Connected components ---")
def find_components(grid, color):
    rows, cols = hfw(grid)
    visited = [[False]*cols for _ in range(rows)]
    comps = []
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == color and not visited[r][c]:
                comp_cells = []
                stack = [(r, c)]
                visited[r][c] = True
                while stack:
                    cr, cc = stack.pop()
                    comp_cells.append((cr, cc))
                    for dr, dc in [(0,1),(0,-1),(1,0),(-1,0)]:
                        nr, nc = cr+dr, cc+dc
                        if 0<=nr<rows and 0<=nc<cols and grid[nr][nc]==color and not visited[nr][nc]:
                            visited[nr][nc] = True
                            stack.append((nr, nc))
                comps.append(comp_cells)
    return comps

